const callbackData = $input.first().json;
const cq = callbackData.callback_query || callbackData;
const callbackDataText = cq.data || '';

let action = 'unknown';
let orderId = 'unknown';
let clientChatId = 'unknown';

if (callbackDataText && typeof callbackDataText === 'string') {
  const parts = callbackDataText.split('_');

  if (parts[0] === 'accept' || parts[0] === 'refuse') {
    action = parts[0];
    clientChatId = parts[1] || 'unknown';
    orderId = parts.length >= 3 ? parts.slice(2).join('_') : 'unknown';
  }
  else if (parts[0] === 'parti' || parts[0] === 'livre') {
    action = parts[0];
    clientChatId = parts[1] || 'unknown';
    orderId = parts.length >= 3 ? parts.slice(2).join('_') : 'unknown';
  }
  else if (parts[0] === 'en' && parts[1] === 'route') {
    action = 'en_route';
    clientChatId = parts[2] || 'unknown';
    orderId = parts.length >= 4 ? parts.slice(3).join('_') : 'unknown';
  }
}

let statut_livraison = '';
let position = '';
let message_client = '';
let message_groupe = '';

if (action === 'accept') {
  statut_livraison = 'accepte';
  position = 'Course acceptee';
  message_client = 'Votre commande est en route !';
  message_groupe = 'Course acceptee';
} else if (action === 'refuse') {
  statut_livraison = 'refusee';
  position = 'Course refusee';
  message_client = 'Nous cherchons un autre livreur.';
  message_groupe = 'Course refusee.';
} else if (action === 'parti') {
  statut_livraison = 'parti';
  position = 'Le livreur a quitte la boutique';
  message_client = 'Votre livreur a recupere votre commande ! Il arrive dans 30-40 minutes.';
  message_groupe = 'Parti de la boutique';
} else if (action === 'en_route') {
  statut_livraison = 'en_route';
  position = 'Le livreur est en route';
  message_client = 'Votre livreur est en route ! Il arrive dans 10-15 minutes.';
  message_groupe = 'Livreur en route';
} else if (action === 'livre') {
  statut_livraison = 'livre';
  position = 'Commande livree';
  message_client = 'Votre commande a ete livree ! Merci de votre confiance.';
  message_groupe = 'Commande livree';
} else {
  statut_livraison = action;
  position = 'Mise a jour';
  message_client = 'Mise a jour de votre livraison';
  message_groupe = 'Mise a jour';
}

const livreurId = cq.from ? cq.from.id : null;
const livreurName = cq.from ? (cq.from.first_name || cq.from.username || 'Inconnu') : 'Inconnu';
const chatIdGroupe = cq.message && cq.message.chat ? cq.message.chat.id : null;

return [{
  json: {
    order_id: orderId,
    client_chat_id: clientChatId,
    action: action,
    statut_livraison: statut_livraison,
    position: position,
    message_client: message_client,
    message_groupe: message_groupe,
    livreur_id: livreurId,
    livreur_name: livreurName,
    chat_id_groupe: chatIdGroupe,
    skip: false
  }
}];

const items = $input.all();
const attendu = String($('Code in JavaScript').first().json.order_id || '').trim();

// La feuille n'est plus interrogee par chat_id mais par order_id : elle ne
// devrait rendre qu'une seule ligne. On verifie tout de meme la
// correspondance, parce qu'un doublon dans la feuille suffirait a
// reintroduire la confusion qu'on vient de supprimer.
if (items.length === 0) {
  throw new Error(`Commande ${attendu} introuvable dans la feuille — callback livreur non traite.`);
}

const ligne = items.find(i => String(i.json.order_id || '').trim() === attendu);
if (!ligne) {
  throw new Error(`Commande ${attendu} absente des ${items.length} ligne(s) remontees — appariement impossible.`);
}

// La ligne est rendue telle quelle : c'est « Corriger telephone », en aval,
// qui normalise le numero. La correction faite ici etait morte, « Preparer
// donnees Switch » ecrasant la valeur juste apres.
return [{ json: ligne.json }];

const items = $input.all();

return items.map(item => {
  let phone = String(item.json.phone || '');

  // Supprimer tous les espaces, tirets, points
  phone = phone.replace(/[\s\-.]/g, '');

  // Ajouter des zéros au début pour avoir 10 chiffres
  phone = phone.padStart(10, '0');

  // Si le numéro fait plus de 10 chiffres, garder les 10 derniers
  if (phone.length > 10) {
    phone = phone.slice(-10);
  }

  return {
    json: {
      ...item.json,
      phone: phone
    }
  };
});

const base  = $('Code in JavaScript').first().json;
const fiche = $('When Executed by Another Workflow').first().json || {};

// Le marchand n'est plus devine : le routeur Telegram l'a deja resolu a
// partir du slug de l'URL du webhook, et nous passe sa fiche. L'ancienne
// version le cherchait dans l'onglet Marchands par l'identifiant du groupe
// livreurs, et retombait sur « zahara » quand elle ne trouvait pas — ce qui
// ecrivait les commandes d'un marchand dans la feuille d'un autre.
return [{ json: { ...base,
  slug:              String(fiche.slug || ''),
  boutique_id:       String(fiche.slug || ''),
  nom_boutique:      String(fiche.nom_boutique || ''),
  sheetCommandes:    String(fiche.sheet_commandes || ''),
  sheet_document_id: String(fiche.sheet_document_id || ''),
  telegram_marchand: String(fiche.telegram_marchand || ''),
} }];

