// Qui livre, et comment le joindre.
//
// Le prenom vient de Telegram : immediat, toujours la. Le nom et le numero
// viennent de la fiche que le marchand a saisie dans son tableau de bord, et
// n'existent que si le livreur a rattache son compte en ouvrant son lien
// d'invitation.
//
// L'annuaire a brievement vecu dans un onglet Google Sheets. C'etait une
// erreur : cette feuille est la tuyauterie de n8n, pas l'espace de travail du
// marchand, et Google y rangeait « 0102030405 » comme un nombre en avalant le
// zero de tete. Le numero vient desormais d'un champ texte de Supabase et se
// transmet tel que le marchand l'a ecrit : aucune retouche, donc aucun moyen
// de casser un numero qui marchait.
const base = $('Code in JavaScript').first().json;
const id = String(base.livreur_id ?? '').trim();
const nomTelegram = String(base.livreur_name || '').trim();

// « Chercher fiche livreur » porte onError continueRegularOutput : une
// plateforme injoignable rend un item d'erreur au lieu de lever. On distingue
// « lecture impossible » de « livreur pas encore rattache », parce que la
// premiere merite un jour d'etre remontee et la seconde est banale.
let fiche = null;
let lecture_ok = true;
try {
  const r = $('Chercher fiche livreur').first().json || {};
  if (r.error || r.ok !== true) lecture_ok = false;
  else if (r.trouve === true) fiche = r;
} catch (e) {
  lecture_ok = false;
}

const nom = String((fiche && fiche.nom) || '').trim()
  || (nomTelegram === 'Inconnu' ? '' : nomTelegram);
const telephone = String((fiche && fiche.telephone) || '').trim();

// LE CLIENT NE DOIT JAMAIS RESTER SANS PERSONNE A APPELER.
//
// Un livreur non rattache est un cas NORMAL : il rejoint le groupe Telegram du
// marchand sans ouvrir son lien d'invitation, et n'existe donc dans aucun
// annuaire. Le client recevait alors « Livreur : Jean Paul » — un prenom,
// parfois orne d'emojis, et rien pour joindre qui que ce soit si sa commande
// tarde. Constate le 20 aout 2026 chez Rose Monde, qui n'a aucun livreur
// enregistre.
//
// Le numero de la boutique est un repli legitime : il est deja public sur la
// vitrine, et c'est le marchand qui repond de sa livraison.
let telephoneBoutique = '';
try {
  telephoneBoutique = String(($('Chercher fiche livreur').first().json || {}).telephone_boutique || '').trim();
} catch (e) {
  telephoneBoutique = '';
}

// La ligne est assemblee ici, pas dans le gabarit du message : un gabarit ne
// sait pas taire une valeur absente, il ecrit « Livreur : » suivi de rien —
// exactement ce qu'a recu le client le 16 aout.
let ligne_client = '';
if (nom && telephone) ligne_client = `🛵 Livreur : ${nom} — ${telephone}\n`;
else if (nom) ligne_client = `🛵 Livreur : ${nom}\n`;

// Faute du numero du livreur, celui de la boutique. Jamais les deux : deux
// numeros dans un meme message, c'est un client qui ne sait pas lequel appeler.
if (!telephone && telephoneBoutique) {
  ligne_client += `📞 Une question ? Appelez la boutique au ${telephoneBoutique}\n`;
}

return [{ json: {
  livreur_id: id,
  nom,
  telephone,
  ligne_client,
  rattache: !!fiche,
  lecture_ok,
} }];

